import React, { useState } from 'react';
import './App.css';

const API_URL = 'http://localhost:5000/api';

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [symbol, setSymbol] = useState('RELIANCE');
  const [price, setPrice] = useState(null);
  const [quantity, setQuantity] = useState(1);
  const [balance, setBalance] = useState(0);
  const [portfolio, setPortfolio] = useState([]);

  const register = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, email, password })
      });
      const data = await response.json();
      setMessage(data.message || data.error);
    } catch (error) {
      setMessage('Error connecting to server. Is Flask running?');
    }
    setLoading(false);
  };

  const login = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ username, password })
      });
      const data = await response.json();
      if (data.message) {
        setIsLoggedIn(true);
        setMessage(`Welcome ${username}!`);
        fetchBalance();
      } else {
        setMessage(data.error || 'Login failed');
      }
    } catch (error) {
      setMessage('Error connecting to server. Is Flask running?');
    }
    setLoading(false);
  };

  const fetchBalance = async () => {
    try {
      const response = await fetch(`${API_URL}/portfolio`, {
        credentials: 'include'
      });
      const data = await response.json();
      if (data.balance !== undefined) {
        setBalance(data.balance);
        setPortfolio(data.portfolio || []);
      }
    } catch (error) {
      console.error('Error fetching balance:', error);
    }
  };

  const getPrice = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/price/${symbol}`);
      const data = await response.json();
      if (data.price) {
        setPrice(data.price);
        setMessage(`Price: ₹${data.price}`);
      } else {
        setMessage('Symbol not found');
      }
    } catch (error) {
      setMessage('Error fetching price');
    }
    setLoading(false);
  };

  const buyStock = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/buy`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ symbol, quantity: parseInt(quantity) })
      });
      const data = await response.json();
      setMessage(data.message || data.error);
      if (data.balance !== undefined) {
        setBalance(data.balance);
        fetchBalance();
      }
    } catch (error) {
      setMessage('Error buying stock');
    }
    setLoading(false);
  };

  const sellStock = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/sell`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ symbol, quantity: parseInt(quantity) })
      });
      const data = await response.json();
      setMessage(data.message || data.error);
      if (data.balance !== undefined) {
        setBalance(data.balance);
        fetchBalance();
      }
    } catch (error) {
      setMessage('Error selling stock');
    }
    setLoading(false);
  };

  const logout = async () => {
    await fetch(`${API_URL}/logout`, {
      method: 'POST',
      credentials: 'include'
    });
    setIsLoggedIn(false);
    setMessage('Logged out');
  };

  if (!isLoggedIn) {
    return (
      <div style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        minHeight: '100vh',
        background: '#0a0e17',
        color: 'white',
        fontFamily: 'Arial'
      }}>
        <div style={{
          background: '#141b2b',
          padding: '40px',
          borderRadius: '12px',
          width: '100%',
          maxWidth: '400px',
          border: '1px solid #2a3a5c'
        }}>
          <h1 style={{ textAlign: 'center', color: '#4CAF50' }}>📈 Demo Trader</h1>
          <p style={{ textAlign: 'center', color: '#4CAF50' }}>🎉 Get ₹1,00,000 FREE!</p>
          
          {message && <div style={{
            padding: '10px',
            margin: '10px 0',
            borderRadius: '6px',
            background: '#1a2332',
            textAlign: 'center'
          }}>{message}</div>}
          
          <h2 style={{ color: '#8a9bb5', fontSize: '18px', marginTop: '20px' }}>Login</h2>
          <input
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            style={{
              width: '100%',
              padding: '12px',
              margin: '8px 0',
              background: '#1a2332',
              border: '1px solid #2a3a5c',
              borderRadius: '6px',
              color: 'white'
            }}
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{
              width: '100%',
              padding: '12px',
              margin: '8px 0',
              background: '#1a2332',
              border: '1px solid #2a3a5c',
              borderRadius: '6px',
              color: 'white'
            }}
          />
          <button
            onClick={login}
            disabled={loading}
            style={{
              width: '100%',
              padding: '12px',
              marginTop: '10px',
              background: '#4CAF50',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              fontSize: '16px',
              fontWeight: 'bold',
              cursor: 'pointer'
            }}
          >
            {loading ? '...' : 'Login'}
          </button>
          
          <h2 style={{ color: '#8a9bb5', fontSize: '18px', marginTop: '20px' }}>Register</h2>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={{
              width: '100%',
              padding: '12px',
              margin: '8px 0',
              background: '#1a2332',
              border: '1px solid #2a3a5c',
              borderRadius: '6px',
              color: 'white'
            }}
          />
          <button
            onClick={register}
            disabled={loading}
            style={{
              width: '100%',
              padding: '12px',
              marginTop: '10px',
              background: '#4CAF50',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              fontSize: '16px',
              fontWeight: 'bold',
              cursor: 'pointer'
            }}
          >
            {loading ? '...' : 'Register & Get ₹1L'}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={{
      minHeight: '100vh',
      background: '#0a0e17',
      color: 'white',
      fontFamily: 'Arial'
    }}>
      <nav style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        padding: '15px 30px',
        background: '#141b2b',
        borderBottom: '1px solid #2a3a5c'
      }}>
        <h2 style={{ color: '#4CAF50' }}>📈 DemoTrader</h2>
        <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
          <span>👤 {username}</span>
          <span style={{
            background: '#1a2332',
            padding: '8px 16px',
            borderRadius: '6px',
            border: '1px solid #2a3a5c'
          }}>💰 ₹{balance.toFixed(2)}</span>
          <button
            onClick={logout}
            style={{
              padding: '8px 16px',
              background: '#dc3545',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              cursor: 'pointer'
            }}
          >
            Logout
          </button>
        </div>
      </nav>

      <div style={{ padding: '30px' }}>
        {message && <div style={{
          padding: '10px',
          marginBottom: '20px',
          borderRadius: '6px',
          background: '#1a2332',
          textAlign: 'center'
        }}>{message}</div>}

        <div style={{
          maxWidth: '600px',
          background: '#141b2b',
          padding: '20px',
          borderRadius: '10px',
          border: '1px solid #2a3a5c',
          marginBottom: '20px'
        }}>
          <h3>Trade</h3>
          <div style={{ display: 'flex', gap: '10px', marginBottom: '15px' }}>
            <input
              type="text"
              value={symbol}
              onChange={(e) => setSymbol(e.target.value.toUpperCase())}
              placeholder="Symbol (e.g., RELIANCE)"
              style={{
                flex: 1,
                padding: '10px',
                background: '#1a2332',
                border: '1px solid #2a3a5c',
                borderRadius: '6px',
                color: 'white'
              }}
            />
            <button
              onClick={getPrice}
              disabled={loading}
              style={{
                padding: '10px 20px',
                background: '#2a3a5c',
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                cursor: 'pointer'
              }}
            >
              Get Price
            </button>
          </div>
          
          {price && (
            <div style={{ textAlign: 'center', marginBottom: '15px' }}>
              <h2>{symbol}</h2>
              <div style={{ fontSize: '32px', fontWeight: 'bold' }}>₹{price.toFixed(2)}</div>
            </div>
          )}
          
          <div style={{ marginBottom: '15px' }}>
            <label style={{ display: 'block', marginBottom: '5px', color: '#8a9bb5' }}>Quantity</label>
            <input
              type="number"
              min="1"
              value={quantity}
              onChange={(e) => setQuantity(e.target.value)}
              style={{
                width: '100%',
                padding: '10px',
                background: '#1a2332',
                border: '1px solid #2a3a5c',
                borderRadius: '6px',
                color: 'white'
              }}
            />
          </div>
          
          <div style={{ display: 'flex', gap: '10px' }}>
            <button
              onClick={buyStock}
              disabled={loading}
              style={{
                flex: 1,
                padding: '12px',
                background: '#4CAF50',
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                fontSize: '16px',
                fontWeight: 'bold',
                cursor: 'pointer'
              }}
            >
              {loading ? '...' : 'BUY'}
            </button>
            <button
              onClick={sellStock}
              disabled={loading}
              style={{
                flex: 1,
                padding: '12px',
                background: '#dc3545',
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                fontSize: '16px',
                fontWeight: 'bold',
                cursor: 'pointer'
              }}
            >
              {loading ? '...' : 'SELL'}
            </button>
          </div>
        </div>

        <div style={{
          background: '#141b2b',
          padding: '20px',
          borderRadius: '10px',
          border: '1px solid #2a3a5c'
        }}>
          <h3>Portfolio</h3>
          {portfolio.length === 0 ? (
            <p>No holdings yet. Start trading!</p>
          ) : (
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead>
                <tr style={{ color: '#8a9bb5', textAlign: 'left' }}>
                  <th style={{ padding: '10px' }}>Symbol</th>
                  <th style={{ padding: '10px' }}>Qty</th>
                  <th style={{ padding: '10px' }}>Avg Price</th>
                  <th style={{ padding: '10px' }}>Current</th>
                  <th style={{ padding: '10px' }}>P&L</th>
                </tr>
              </thead>
              <tbody>
                {portfolio.map((item) => (
                  <tr key={item.symbol}>
                    <td style={{ padding: '10px', borderTop: '1px solid #2a3a5c' }}>{item.symbol}</td>
                    <td style={{ padding: '10px', borderTop: '1px solid #2a3a5c' }}>{item.quantity}</td>
                    <td style={{ padding: '10px', borderTop: '1px solid #2a3a5c' }}>₹{item.avg_price.toFixed(2)}</td>
                    <td style={{ padding: '10px', borderTop: '1px solid #2a3a5c' }}>₹{item.current_price.toFixed(2)}</td>
                    <td style={{
                      padding: '10px',
                      borderTop: '1px solid #2a3a5c',
                      color: item.pnl >= 0 ? '#4CAF50' : '#dc3545'
                    }}>
                      ₹{item.pnl.toFixed(2)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
          <div style={{ marginTop: '15px', padding: '15px', background: '#1a2332', borderRadius: '6px' }}>
            💰 Balance: ₹{balance.toFixed(2)}
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
